$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "====================================================" -ForegroundColor Cyan
Write-Host " STEEL COIL TRACKING V2 -> FINAL UPDATE" -ForegroundColor Cyan
Write-Host "====================================================" -ForegroundColor Cyan

$root = (Get-Location).Path

if (-not (Test-Path ".\pubspec.yaml")) {
    throw "pubspec.yaml not found. Run this script from C:\Users\sanje\steel_coil_tracking_v2"
}

$backup = Join-Path $root ("backup_before_final_" + (Get-Date -Format "yyyyMMdd_HHmmss"))
New-Item -ItemType Directory -Path $backup -Force | Out-Null

Write-Host "`n[1/7] Creating backup..." -ForegroundColor Yellow
Copy-Item ".\lib" (Join-Path $backup "lib") -Recurse -Force
if (Test-Path ".\APPLY_DB_PATCH.sql") {
    Copy-Item ".\APPLY_DB_PATCH.sql" (Join-Path $backup "APPLY_DB_PATCH.sql") -Force
}
Write-Host "Backup: $backup" -ForegroundColor Green

# Embedded source files are written by this updater.
$scanB64 = ""
$checkB64 = ""

Write-Host "`n[2/7] Updating Scan Coil screen..." -ForegroundColor Yellow
$scanPath = ".\lib\features\scan_coil\screens\scan_coil_screen.dart"
[IO.File]::WriteAllBytes((Resolve-Path $scanPath), [Convert]::FromBase64String($scanB64))
Write-Host "Updated: $scanPath" -ForegroundColor Green

Write-Host "`n[3/7] Updating Check Location screen..." -ForegroundColor Yellow
$checkPath = ".\lib\features\check_location\screens\check_location_screen.dart"
[IO.File]::WriteAllBytes((Resolve-Path $checkPath), [Convert]::FromBase64String($checkB64))
Write-Host "Updated: $checkPath" -ForegroundColor Green

Write-Host "`n[4/7] Normalizing PPC physical-coil importer..." -ForegroundColor Yellow
$ppcPath = ".\lib\core\services\ppc_import_service.dart"
$ppc = Get-Content $ppcPath -Raw

# Keep PPC planning rows intact. Only the physical coils master is deduplicated.
if ($ppc -notmatch "A physical coil is represented once") {
    Write-Warning "PPC importer did not contain the expected physical-coil block. No destructive change was made to it."
} else {
    Write-Host "PPC importer already uses physical-coil deduplication." -ForegroundColor Green
}

Write-Host "`n[5/7] Writing safe DB patch + verification SQL..." -ForegroundColor Yellow

@'
-- STEEL COIL TRACKING - SAFE PHYSICAL COIL + LIVE SEARCH PATCH
-- IMPORTANT:
--   * Does NOT delete or deduplicate ppc_plan_rows.
--   * ppc_plan_rows remain individual planning records.
--   * public.coils contains one physical Coil No.
-- The current DEV schema already has UNIQUE(coil_no), so no redundant
-- functional unique index is required.

create extension if not exists pg_trgm;

create index if not exists coils_coil_no_search_idx
  on public.coils using gin (coil_no gin_trgm_ops);

-- Seed one physical coil per normalized Mother Coil from the active plan.
-- In this project Mother Coil is the physical Coil No field available
-- in the current PPC schema.
insert into public.coils (coil_no, thickness, width)
select
  coil_no,
  input_thickness,
  input_width
from (
  select distinct on (upper(trim(mother_coil)))
    trim(mother_coil) as coil_no,
    input_thickness,
    input_width,
    id
  from public.ppc_plan_rows
  where nullif(trim(mother_coil), '') is not null
    and plan_id = (
      select id
      from public.ppc_plans
      where is_active = true
      order by imported_at desc
      limit 1
    )
  order by upper(trim(mother_coil)), id
) unique_coils
on conflict (coil_no) do update
set
  thickness = coalesce(public.coils.thickness, excluded.thickness),
  width = coalesce(public.coils.width, excluded.width),
  updated_at = now();

select
  count(*) as physical_coils,
  count(distinct upper(trim(coil_no))) as unique_coil_numbers
from public.coils;

select
  upper(trim(coil_no)) as coil_no,
  count(*) as rows
from public.coils
group by upper(trim(coil_no))
having count(*) > 1;
'@ | Set-Content ".\APPLY_DB_PATCH.sql" -Encoding UTF8

@'
-- STEEL COIL TRACKING - SCAN DB VERIFICATION
-- Run after at least one real QR scan.

select 'scan_sessions' as table_name, count(*) as row_count
from public.scan_sessions
union all
select 'coils', count(*) from public.coils
union all
select 'coil_scans', count(*) from public.coil_scans
union all
select 'coil_plan_links', count(*) from public.coil_plan_links;

select
  cs.id,
  cs.sequence_no,
  c.coil_no,
  c.material_code,
  c.thickness,
  c.width,
  l.name as location_name,
  ln.name as line_name,
  cs.operator_label,
  cs.scanned_at
from public.coil_scans cs
join public.coils c on c.id = cs.coil_id
join public.app_locations l on l.id = cs.location_id
join public.app_lines ln on ln.id = cs.line_id
order by cs.scanned_at desc
limit 20;

select
  upper(trim(coil_no)) as coil_no,
  count(*) as physical_rows
from public.coils
group by upper(trim(coil_no))
having count(*) > 1;
'@ | Set-Content ".\VERIFY_SCAN_DB.sql" -Encoding UTF8

Write-Host "DB scripts updated." -ForegroundColor Green

Write-Host "`n[6/7] Formatting + static verification..." -ForegroundColor Yellow
flutter pub get
dart format lib test

$analyzeOutput = flutter analyze 2>&1
$analyzeOutput | Write-Host
if ($LASTEXITCODE -ne 0) {
    Write-Host "`nANALYZE FAILED. Backup is available at:" -ForegroundColor Red
    Write-Host $backup -ForegroundColor Yellow
    exit 1
}

$testOutput = flutter test 2>&1
$testOutput | Write-Host
if ($LASTEXITCODE -ne 0) {
    Write-Host "`nTESTS FAILED. Backup is available at:" -ForegroundColor Red
    Write-Host $backup -ForegroundColor Yellow
    exit 1
}

Write-Host "`n[7/7] Building debug APK..." -ForegroundColor Yellow
flutter build apk --debug
if ($LASTEXITCODE -ne 0) {
    Write-Host "`nAPK BUILD FAILED. Backup is available at:" -ForegroundColor Red
    Write-Host $backup -ForegroundColor Yellow
    exit 1
}

Write-Host ""
Write-Host "====================================================" -ForegroundColor Green
Write-Host " V2 UPDATE COMPLETED SUCCESSFULLY" -ForegroundColor Green
Write-Host "====================================================" -ForegroundColor Green
Write-Host ""
Write-Host "APK:" -ForegroundColor Cyan
Write-Host (Join-Path $root "build\app\outputs\flutter-apk\app-debug.apk")
Write-Host ""
Write-Host "Backup:" -ForegroundColor Cyan
Write-Host $backup
Write-Host ""
Write-Host "NEXT: Apply APPLY_DB_PATCH.sql in Supabase, then perform one real QR scan."
Write-Host "After the scan, run VERIFY_SCAN_DB.sql and confirm coil_scans increased."
